// The SFR view's data (peripheral registers from ST's SVD) and the
// arithmetic on register values: field decode and encode, and the
// read-modify-write that changes one field. No React here, so the unit
// tests (test/sfr.test.ts) run it in Node.
//
// The description comes from web/public/sfr/STM32F401.json, generated by
// tools/svdjson.py (its docstring has the format), and is fetched only when
// the SFR tab first opens.

export type Access = "rw" | "r" | "w";
/** How a write acts on a field besides storing it: w0c — a 0 clears the
 * flag, a 1 changes nothing (rc_w0: TIMx_SR, USART_SR); w1c — a 1 clears
 * the flag or starts the action (rc_w1: EXTI_PR, FLASH_SR, RCC_CSR.RMVF). */
export type WriteEffect = "w0c" | "w1c";

export interface SfrEnum {
  value: number;
  name: string;
  desc: string;
}

export interface SfrField {
  name: string;
  lsb: number;
  width: number;
  access: Access;
  effect?: WriteEffect;
  desc: string;
  enums: SfrEnum[];
}

export interface SfrRegister {
  name: string;
  offset: number;
  /** Absolute address. */
  addr: number;
  /** Bits (32 on this part). */
  size: number;
  access: Access;
  reset: number;
  desc: string;
  fields: SfrField[];
}

export interface SfrPeripheral {
  name: string;
  base: number;
  group: string;
  desc: string;
  interrupts: [string, number][];
  registers: SfrRegister[];
}

/** The generated file's shape (short keys, see tools/svdjson.py). */
interface RawField {
  n: string;
  l: number;
  w: number;
  a?: Access;
  m?: WriteEffect;
  d?: string;
  e?: [number, string, string][];
}
interface RawRegister {
  n: string;
  o: number;
  z?: number;
  a: Access;
  r: number;
  d?: string;
  f: RawField[];
}
export interface SvdJson {
  device: string;
  p: { n: string; b: number; g: string; d: string; i?: [string, number][]; r: number }[];
  s: RawRegister[][];
}

/** The peripherals of the generated description, sorted by base address. */
export function parseSvdJson(json: SvdJson): SfrPeripheral[] {
  return json.p.map((p) => ({
    name: p.n,
    base: p.b >>> 0,
    group: p.g,
    desc: p.d,
    interrupts: p.i ?? [],
    registers: json.s[p.r].map((r) => ({
      name: r.n,
      offset: r.o,
      addr: (p.b + r.o) >>> 0,
      size: r.z ?? 32,
      access: r.a,
      reset: r.r >>> 0,
      desc: r.d ?? "",
      fields: r.f.map((f) => ({
        name: f.n,
        lsb: f.l,
        width: f.w,
        access: f.a ?? r.a,
        effect: f.m,
        desc: f.d ?? "",
        enums: (f.e ?? []).map(([value, name, desc]) => ({ value, name, desc })),
      })),
    })),
  }));
}

let loading: Promise<SfrPeripheral[]> | null = null;

/** Fetch the description once (the service worker has it offline). */
export function loadSfr(url = "./sfr/STM32F401.json"): Promise<SfrPeripheral[]> {
  loading ??= fetch(url)
    .then((r) => {
      if (!r.ok) throw new Error(`${url}: ${r.status}`);
      return r.json() as Promise<SvdJson>;
    })
    .then(parseSvdJson)
    .catch((e: unknown) => {
      loading = null; // try again next time
      throw e;
    });
  return loading;
}

/** The bits of `f` in its register. */
export function fieldMask(f: Pick<SfrField, "lsb" | "width">): number {
  const ones = f.width >= 32 ? 0xffffffff : (1 << f.width) - 1;
  return (ones << f.lsb) >>> 0;
}

/** The value of field `f` in register value `reg`. */
export function fieldValue(reg: number, f: Pick<SfrField, "lsb" | "width">): number {
  return ((reg >>> 0) & fieldMask(f)) >>> f.lsb;
}

/** `reg` with field `f` set to `v` (bits of `v` beyond the field are dropped). */
export function withField(reg: number, f: Pick<SfrField, "lsb" | "width">, v: number): number {
  const m = fieldMask(f);
  return ((reg & ~m) | ((v << f.lsb) & m)) >>> 0;
}

/** Bit range as the reference manual writes it: "[5]" or "[15:8]". */
export function bitRange(f: Pick<SfrField, "lsb" | "width">): string {
  return f.width === 1 ? `[${f.lsb}]` : `[${f.lsb + f.width - 1}:${f.lsb}]`;
}

/** The enumerated value's name for `v`, if the description has one. */
export function enumName(f: SfrField, v: number): string | null {
  return f.enums.find((e) => e.value === v)?.name ?? null;
}

/**
 * The word to write so that only field `field` of `reg` becomes `v`, from
 * the register's current (peeked) value `current`:
 * - a write-only register starts from 0 (it reads 0 anyway);
 * - another field that a 1 clears (w1c) gets 0 where the peripheral has
 *   a model, or writing back a set flag would clear it; a register-file
 *   peripheral stores the word as written, so it gets the current value
 *   back (a 0 there would erase the bit);
 * - another field that a 0 clears (w0c) gets 1 where the peripheral has a
 *   model (a 1 changes nothing there, and a flag that was set after the
 *   value was read stays set); a register-file peripheral keeps what it
 *   stores, so it gets the current value back;
 * - everything else is written back as it was read.
 */
export function fieldWrite(reg: SfrRegister, current: number, field: SfrField, v: number, modelled: boolean): number {
  let word = reg.access === "w" ? 0 : current >>> 0;
  for (const f of reg.fields) {
    if (f === field) continue;
    if (f.effect === "w1c" && modelled) word &= ~fieldMask(f);
    else if (f.effect === "w0c" && modelled) word |= fieldMask(f);
  }
  return withField(word >>> 0, field, v);
}

/** Parse what was typed in a value box: hex with 0x, binary with 0b, else decimal (null: not a number). */
export function parseValue(text: string, hexDefault = false): number | null {
  const s = text.trim().replace(/_/g, "").toLowerCase();
  let n: number;
  if (/^0x[0-9a-f]+$/.test(s)) n = parseInt(s.slice(2), 16);
  else if (/^0b[01]+$/.test(s)) n = parseInt(s.slice(2), 2);
  else if (hexDefault && /^[0-9a-f]+$/.test(s)) n = parseInt(s, 16);
  else if (/^\d+$/.test(s)) n = parseInt(s, 10);
  else return null;
  return n <= 0xffffffff ? n >>> 0 : null;
}

export const hex32 = (v: number) => "0x" + (v >>> 0).toString(16).toUpperCase().padStart(8, "0");

/** "GPIOA.ODR": how a register is named in the watched list (and kept). */
export const regKey = (p: SfrPeripheral, r: SfrRegister) => `${p.name}.${r.name}`;

/** The peripheral and register a key names. */
export function findReg(list: SfrPeripheral[], key: string): { p: SfrPeripheral; r: SfrRegister } | null {
  const dot = key.indexOf(".");
  const p = list.find((x) => x.name === key.slice(0, dot));
  const r = p?.registers.find((x) => x.name === key.slice(dot + 1));
  return p && r ? { p, r } : null;
}

export interface FilterHit {
  p: SfrPeripheral;
  /** The registers to list when the peripheral is open. */
  registers: SfrRegister[];
  /** The query matched registers or fields, not the peripheral: open it. */
  open: boolean;
  /** Registers whose fields matched: open them. */
  openRegs: Set<string>;
}

/**
 * Peripherals that match `query` (case-insensitive substring): by
 * peripheral name or group (all registers), else by register or field
 * name (those registers). "GPIOA.ODR" narrows to a register of a
 * peripheral, "TIM2.CNT" and "USART2.SR.RXNE" alike.
 */
export function filterSfr(list: SfrPeripheral[], query: string): FilterHit[] {
  const q = query.trim().toLowerCase();
  if (!q) return list.map((p) => ({ p, registers: p.registers, open: false, openRegs: new Set() }));
  const parts = q.split(".");
  if (parts.length > 1 && parts[0]) {
    const [pq, rq, fq = ""] = parts;
    const out: FilterHit[] = [];
    for (const p of list) {
      if (!p.name.toLowerCase().includes(pq)) continue;
      const regs = p.registers.filter(
        (r) => r.name.toLowerCase().includes(rq) && (!fq || r.fields.some((f) => f.name.toLowerCase().includes(fq))),
      );
      if (regs.length) out.push({ p, registers: regs, open: true, openRegs: new Set(fq ? regs.map((r) => r.name) : []) });
    }
    return out;
  }
  const out: FilterHit[] = [];
  for (const p of list) {
    if (p.name.toLowerCase().includes(q) || p.group.toLowerCase() === q) {
      out.push({ p, registers: p.registers, open: false, openRegs: new Set() });
      continue;
    }
    const openRegs = new Set<string>();
    const regs = p.registers.filter((r) => {
      if (r.name.toLowerCase().includes(q)) return true;
      if (r.fields.some((f) => f.name.toLowerCase().includes(q))) {
        openRegs.add(r.name);
        return true;
      }
      return false;
    });
    if (regs.length) out.push({ p, registers: regs, open: true, openRegs });
  }
  return out;
}

/** Status bits per peripheral from the worker (`Simulator.sfrStatus`). */
export const STATUS_GATED = 1;
export const STATUS_CLOCK_ON = 2;
export const STATUS_MODEL = 4;

const PINNED_KEY = "simucleo.sfr.pinned";

/** The watched registers kept in this browser ([] when storage is unavailable). */
export function loadPinned(storage: Pick<Storage, "getItem"> | undefined = globalThis.localStorage): string[] {
  try {
    const v = JSON.parse(storage?.getItem(PINNED_KEY) ?? "[]") as unknown;
    return Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : [];
  } catch {
    return [];
  }
}

export function savePinned(keys: string[], storage: Pick<Storage, "setItem"> | undefined = globalThis.localStorage) {
  try {
    storage?.setItem(PINNED_KEY, JSON.stringify(keys));
  } catch {
    // Private mode or storage full: the list lasts for this visit only.
  }
}
